const pages=[...document.querySelectorAll('.page')];
const ids=pages.map(p=>p.id);
const dialog=document.querySelector('#project-dialog');
let current=0;
function showPage(){const id=location.hash.slice(1);current=Math.max(0,ids.indexOf(id));pages.forEach((p,i)=>{p.hidden=i!==current});document.querySelector('#page-number').innerHTML=`0${current+1} <span>/ 04</span>`;document.querySelectorAll('nav a,.page-dots a').forEach(a=>{if(a.hash==='#'+ids[current])a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===pages.length-1;document.title=`CCR — ${['想法，成为作品','精选作品','关于我的实践','从你好开始'][current]}`;window.scrollTo(0,0)}
function move(delta){const next=Math.max(0,Math.min(ids.length-1,current+delta));if(next!==current)location.hash=ids[next]}
window.addEventListener('hashchange',showPage);
document.querySelector('#prev').addEventListener('click',()=>move(-1));document.querySelector('#next').addEventListener('click',()=>move(1));
document.addEventListener('keydown',e=>{if(dialog.open||e.altKey||e.ctrlKey||e.metaKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='ArrowRight'||e.key==='PageDown'){e.preventDefault();move(1)}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();move(-1)}});
let touchStart=null;document.querySelector('main').addEventListener('touchstart',e=>{touchStart=[e.changedTouches[0].clientX,e.changedTouches[0].clientY]},{passive:true});document.querySelector('main').addEventListener('touchend',e=>{if(!touchStart||dialog.open)return;const dx=e.changedTouches[0].clientX-touchStart[0],dy=e.changedTouches[0].clientY-touchStart[1];if(Math.abs(dx)>75&&Math.abs(dx)>Math.abs(dy)*1.5)move(dx<0?1:-1);touchStart=null},{passive:true});
const projects={space:{title:'一张图，一个空间',category:'01 / SPACE · BLENDER',image:'space',summary:'从无尺寸平面图出发，建立可编辑的房屋白模，让布局、开口与家具关系变得直观。',process:'整理墙线和门窗开口，建立连续墙壳，再补入家具、门窗及基础硬装。以保存重开后的实际几何核对洞口、尺寸与主要穿插关系。',result:'第二阶段白模已生成，包含4床、3卫及家具硬装，原项目几何检查通过。平面尺寸与部分门型为估算；吊顶待图，不作为施工深化成果。'},film:{title:'把复杂，讲明白',category:'02 / MOTION · HYPERFRAMES',image:'film',summary:'用复古手撕拼贴与动效卡片，把从毛坯到入住的装修流程整理为一段易于观看的科普影像。',process:'编排12个章节、30张提示卡与同步字幕；结合AI工序示意图、普通话配音和时间轴，让选材、工序与验收要点依次展开。',result:'5分钟竖屏MP4已导出，1080×1920、30fps；原项目完成解码与关键帧验证。图片为AI示意，不是同一套房的连续施工实拍。本站展示节选静帧。'},city:{title:'换个视角，看城市',category:'03 / INTERACTION · PANDA3D',image:'city',summary:'以新乡城区为对象，探索从空中观察到地面漫游的交互方式，把地图中的轮廓变成可以进入的空间。',process:'使用开放地图轮廓建立城市沙盘，围绕重点街区补充示意地标、道路、植物与天桥；探索视角切换、登桥路线与碰撞反馈。',result:'当前为开发中交互原型，已进行原项目场景检查。建筑高度、部分外观与设施为示意，数据覆盖尚不完整；不是现实导航或精确城市复原。本站展示项目截图。'}};
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=projects[button.dataset.project];document.querySelector('#detail-title').textContent=p.title;document.querySelector('#detail-category').textContent=p.category;document.querySelector('#detail-image').src=`assets/${p.image}.jpg`;document.querySelector('#detail-image').alt=p.title+'项目画面';['summary','process','result'].forEach(key=>document.querySelector('#detail-'+key).textContent=p[key]);dialog.showModal();dialog.scrollTop=0}));
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.querySelector('#discuss-project').addEventListener('click',()=>{dialog.close();location.hash='contact'});
let intent='项目咨询';document.querySelectorAll('[data-intent]').forEach(b=>b.addEventListener('click',()=>{intent=b.dataset.intent;document.querySelectorAll('[data-intent]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('#copy-status').textContent=''}));
document.querySelector('#copy-brief').addEventListener('click',async()=>{const text=`你好 CCR，我从你的个人网站了解到你的作品，想和你聊聊${intent}。我的需求是：____；预计时间：____；预算或合作方式：____。`;try{await navigator.clipboard.writeText(text);document.querySelector('#copy-status').textContent='已复制，可粘贴到聊天中补充需求。'}catch{document.querySelector('#copy-status').textContent=text}});
